const body = $('Webhook').item.json.body;
const prev = $input.first().json;
const map = JSON.parse($env.N8N_AGENT_MAP || '{}');
const assignees = (body.issue.assignees || []).map(a => a.login);
const matchAssignee = assignees.find(a => map[a] && map[a].role === 'implementer');
const implementerLogin = matchAssignee || $env.N8N_IMPLEMENTER_DEFAULT;
const entry = map[implementerLogin];
if (!entry) {
  throw new Error(`N8N_AGENT_MAP has no implementer entry for login "${implementerLogin}"`);
}
const reviewerLogin = $env.N8N_REVIEWER_DEFAULT;
return [{ json: { ...prev, host: entry.host, sshPort: entry.port, sshUser: entry.user, implementerLogin, reviewerLogin } }];

const j = $input.first().json;
const prompt = `Issue #${j.issueNumber}: ${j.issueTitle}

${j.issueBody}

Implement a fix. Keep the change minimal and focused on the reported problem. Commit with a clear message and exit when done.
`;
return [{ json: { ...j, promptB64: Buffer.from(prompt, 'utf8').toString('base64') } }];
